/** static void PetalburgGymSetDoorMetatiles(u8 roomNumber, u16 metatileId) */
export function PetalburgGymSetDoorMetatiles(roomNumber: any, metatileId: any): any {
  const doorCoordsX: any[] = [];
      const doorCoordsY: any[] = [];
      let i: any = null;
      let nDoors: any = 0;
      switch (roomNumber)
      {
      case 1:
          nDoors = 2;
          doorCoordsX[0] = 1;
          doorCoordsX[1] = 7;
          doorCoordsY[0] = 104;
          doorCoordsY[1] = 104;
          break;
      case 2:
          nDoors = 2;
          doorCoordsX[0] = 1;
          doorCoordsX[1] = 7;
          doorCoordsY[0] = 78;
          doorCoordsY[1] = 78;
          break;
      case 3:
          nDoors = 2;
          doorCoordsX[0] = 1;
          doorCoordsX[1] = 7;
          doorCoordsY[0] = 91;
          doorCoordsY[1] = 91;
          break;
      case 4:
          nDoors = 1;
          doorCoordsX[0] = 7;
          doorCoordsY[0] = 39;
          break;
      case 5:
          nDoors = 2;
          doorCoordsX[0] = 1;
          doorCoordsX[1] = 7;
          doorCoordsY[0] = 52;
          doorCoordsY[1] = 52;
          break;
      case 6:
          nDoors = 1;
          doorCoordsX[0] = 1;
          doorCoordsY[0] = 65;
          break;
      case 7:
          nDoors = 1;
          doorCoordsX[0] = 7;
          doorCoordsY[0] = 13;
          break;
      case 8:
          nDoors = 1;
          doorCoordsX[0] = 1;
          doorCoordsY[0] = 26;
          break;
      }
      for (i = 0; i < nDoors; i++)
      {
          MapGridSetMetatileIdAt(doorCoordsX[i] + MAP_OFFSET, doorCoordsY[i] + MAP_OFFSET, metatileId | MAPGRID_IMPASSABLE);
          MapGridSetMetatileIdAt(doorCoordsX[i] + MAP_OFFSET, doorCoordsY[i] + MAP_OFFSET + 1, (metatileId + METATILE_ROW_WIDTH) | MAPGRID_IMPASSABLE);
      }
      DrawWholeMapView();
}

