/** void MoveElevator(void) */
export function MoveElevator(): any {
  const sElevatorTripLength: any = [ 8, 16, 24, 32, 38, 46, 52, 56, 57 ];

      let data: any = gTasks[CreateTask(Task_MoveElevator, 9)].data;
      let floorDelta: any = null;

      tTimer = 0;
      tMoveCounter = 0;
      tVerticalPan = 1;

      if (gSpecialVar_0x8005 > gSpecialVar_0x8006)
      {
          floorDelta = gSpecialVar_0x8005 - gSpecialVar_0x8006;
          tDescending = TRUE;
      }
      else
      {
          floorDelta = gSpecialVar_0x8006 - gSpecialVar_0x8005;
          tDescending = FALSE;
      }

      if (floorDelta > MAX_ELEVATOR_TRIP - 1)
          floorDelta = MAX_ELEVATOR_TRIP - 1;

      tTotalMoves = sElevatorTripLength[floorDelta];

      SetCameraPanningCallback(NULL);
      MoveElevatorWindowLights(floorDelta, tDescending);
      PlaySE(SE_ELEVATOR);
}

/** static void Task_MoveElevator(u8 taskId) */
export function Task_MoveElevator(taskId: any): any {
  let data: any = gTasks[taskId].data;
      tTimer++;
      if (tTimer % 3 == 0)
      {
          tTimer = 0;
          tMoveCounter++;
          tVerticalPan = -tVerticalPan;
          SetCameraPanning(0, tVerticalPan);

          if (tMoveCounter == tTotalMoves)
          {
               
              PlaySE(SE_DING_DONG);
              DestroyTask(taskId);
              ScriptContext_Enable();
              InstallCameraPanAheadCallback();
          }
      }
}

