          SetPlayerGotFirstFans();
          SetInitialFansOfPlayer();
          gSaveBlock1Ptr.vars[VAR_FANCLUB_LOSE_FAN_TIMER - VARS_START] = gSaveBlock2Ptr.playTimeHours;
          FlagClear(FLAG_HIDE_FANCLUB_OLD_LADY);
